c=canvas.Canvas(str(OUT),pagesize=A4);c.setTitle('GradeCrew Entwicklungswerkzeug - Auftrag und Abnahmeatlas (220 Seiten)');c.setAuthor('GradeCrew / Martin');W,H=A4
for number,page in enumerate(pages,1):
 c.bookmarkPage(page['id']);c.addOutlineEntry(page['title'],page['id'],level=0,closed=True)
 c.setFillColor(NAVY);c.rect(0,H-12,W,12,fill=1,stroke=0);c.setFillColor(GRAY);c.setFont('GCRegular',8.2);c.drawString(46,H-36,'GRADECREW  |  ENTWICKLUNGSWERKZEUG  |  08.10.2026');c.setFillColor(BLUE);c.setFont('GCBold',8.5);c.drawString(46,H-62,page['kind'].upper()+'  '+page['id']);y=H-79
 p=Paragraph(escape(page['title']),TITLE);_,h=p.wrap(W-92,H);p.drawOn(c,46,y-h);y-=h+22
 for heading,body in page['blocks']:
  if heading=='toc':
   for n,ident,title in body:
    text=f'<b>{n:03}</b>  {escape(ident)}  {escape(title)}';p=Paragraph(text,TOC);_,h=p.wrap(W-92,H);p.drawOn(c,46,y-h);y-=h+1
  elif heading=='image':
   image=Image(body);image.drawWidth=W-92;image.drawHeight=image.imageHeight/image.imageWidth*image.drawWidth
   if image.drawHeight>300:image.drawHeight=300;image.drawWidth=image.imageWidth/image.imageHeight*300
   image.drawOn(c,46,y-image.drawHeight);y-=image.drawHeight+12
   p=Paragraph('KI-Entwurf vor Umsetzung. Keine echte App-/Spielabnahme. Späterer kompakter dunkler Werkzeugstil hat Vorrang.',SMALL);_,h=p.wrap(W-92,H);p.drawOn(c,46,y-h);y-=h+8
  else:
   p=Paragraph(escape(heading),HEAD);_,h=p.wrap(W-92,H);p.drawOn(c,46,y-h);y-=h+4
   p=Paragraph(escape(body),STYLE);_,h=p.wrap(W-92,H);p.drawOn(c,46,y-h);y-=h+13
 if y<54:raise RuntimeError(f'Page {number} overflows: {y}')
 c.setStrokeColor(colors.HexColor('#dce5ef'));c.line(46,43,W-46,43);c.setFillColor(GRAY);c.setFont('GCRegular',7.6);c.drawString(46,29,'GC-WEB-REPAIR-20261007 | Auftrag / Abnahme getrennt');c.drawRightString(W-46,29,f'{number} / 220');c.showPage()
c.save();pdf=PdfReader(OUT);assert len(pdf.pages)==220;assert all((p.extract_text() or '').strip() for p in pdf.pages)
